CREATE TABLE post_media ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, post_id BIGINT NOT NULL, media_url TEXT NOT NULL, media_type TEXT NOT NULL CHECK (media_type IN ('image','video')), duration_seconds DOUBLE PRECISION, position INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), deleted_at TIMESTAMPTZ,
CONSTRAINT POST_MEDIA_POST_FK FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE, CONSTRAINT POST_MEDIA_ORDER_UQ UNIQUE (post_id, position) );
CREATE INDEX idx_post_media_post ON post_media(post_id, position) WHERE deleted_at IS NULL;
